-- ===========================================================
-- 0028_crew_lead_sees_price.sql
-- ===========================================================
-- 0028 A crew lead sees what the job is worth
--
-- The crew lead is the person standing in the basement when the wall comes
-- off and there is twice as much rot behind it as anybody quoted for. Until
-- now he could write that up but not see the number it was being measured
-- against, so "this is bigger than the job" was a feeling rather than a
-- figure. Giving him the contract price makes the report he sends the office
-- worth acting on: not "there's more here", but "there's more here and we
-- quoted 8,600 for it".
--
-- Reading a price and moving one are different things, and after 0027 they
-- are enforced differently. Nothing here lets him move it:
--
--   * `jobs.quoted_price` and `change_orders.amount` are not writable by the
--     signed-in role at all — 0027 dropped the table grant and re-granted
--     every other column. No permission flag brings that back.
--   * `set_job_price()` needs job.edit AND price.view. A crew lead has
--     neither job.edit nor any way to get it.
--   * `present_change_order()` and `decide_change_order()` need
--     changeorder.manage. He has changeorder.draft, which raises a draft with
--     no price on it, and the row policy pins it there.
--
-- Three things price.view deliberately does NOT open, because they are
-- separate flags and stay that way:
--
--   * `costing.view` — what the job cost us, and the margin. Still manager
--     and owner only. He sees the price, not the profit.
--   * `user.view_cost_rates` — what his colleagues are paid. Owner only.
--   * The technician role. This is the lead's job, not the whole crew's.

create or replace function provision_org_roles(p_org_id uuid)
returns void
language plpgsql
as $$
begin
  insert into roles (org_id, key, name, is_system, permissions) values
  (p_org_id, 'owner', 'Owner', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.close', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.approve_unlimited', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'user.view_cost_rates', true,
    'role.manage', true, 'org.manage_settings', true, 'audit.view', true,
    'data.restore', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  (p_org_id, 'manager', 'Manager', true, jsonb_build_object(
    'job.view_all', true, 'job.edit', true, 'job.assign', true, 'job.accept', true,
    'job.complete', true, 'job.review', true, 'job.manage_templates', true,
    'reschedule.decide', true, 'customer.manage', true,
    'changeorder.draft', true, 'changeorder.manage', true,
    'inventory.manage', true, 'inventory.log_usage', true, 'inventory.transfer', true,
    'inventory.adjust', true,
    'purchase.approve', true, 'purchase.view_all', true, 'purchase.view_history', true,
    'vehicle.manage', true, 'mileage.view_all', true, 'mileage.edit_all', true,
    'equipment.manage', true, 'equipment.place', true, 'equipment.rental_manage', true,
    'time.view_all', true, 'time.log_others', true, 'time.edit_all', true,
    'timeoff.manage', true, 'user.manage', true, 'audit.view', true,
    'price.view', true, 'costing.view', true, 'export.run', true
  )),

  -- price.view, so he can tell the office the work has outgrown the quote.
  -- No costing.view: the price is not the margin.
  (p_org_id, 'crew_lead', 'Crew Lead', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true, 'inventory.transfer', true,
    'equipment.place', true,
    'time.log_others', true,
    'price.view', true
  )),

  -- Still no price. A technician is told what to do, not what it is worth.
  (p_org_id, 'technician', 'Technician', true, jsonb_build_object(
    'job.accept', true, 'job.complete', true,
    'changeorder.draft', true,
    'inventory.log_usage', true,
    'equipment.place', true
  )),

  -- Keeps the books, so needs the price but never the margin conversation.
  -- audit.view lets them read the trail; nothing here lets them change it.
  (p_org_id, 'bookkeeper', 'Bookkeeper', true, jsonb_build_object(
    'job.view_all', true,
    'purchase.view_all', true, 'purchase.view_history', true,
    'mileage.view_all', true, 'time.view_all', true,
    'audit.view', true, 'price.view', true, 'costing.view', true, 'export.run', true,
    'job.close', true
  ))
  on conflict (org_id, key) do nothing;
end;
$$;

-- Orgs that already exist. Only the system crew_lead role, and only where the
-- flag is not already set — an owner who turned it off by hand meant it.
update roles
   set permissions = permissions || '{"price.view": true}'::jsonb
 where key = 'crew_lead'
   and is_system
   and coalesce((permissions ->> 'price.view')::boolean, false) = false;

-- ===========================================================
-- 0029_crew_pay.sql
-- ===========================================================
-- 0029 What the crew was paid for the job
--
-- Crews here are paid a flat amount per job, not by the hour. Nothing records
-- hours and nothing should, so `job_labour_cost()` returned zero for every
-- job and `job_costs.margin` was contract price minus everything except the
-- largest cost on it. On a 9,850 job with a thousand pounds of materials and
-- equipment that reads as an 8,800 margin, which is not a small error — it is
-- the wrong answer to the only question the costing screens exist to answer.
--
-- One line per payment. The office records what was agreed, as one lump for
-- the crew or a line each, whichever matches how the job was actually paid.
--
-- Two decisions worth stating, because both could reasonably go the other way:
--
--   1. `user_id` is optional. "3,200 to Marcus's crew" is how a lot of these
--      get agreed, and forcing a split across names would invent detail that
--      was never decided. Name someone when the job was paid per person.
--
--   2. This is a cost, not payroll. It is what the job cost the company, so
--      it sits behind costing.view with margin and job cost, and it never
--      reaches the field app. What an individual takes home over a year is a
--      payroll question, and this app is not the place for it.

create table job_crew_pay (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references organizations(id) on delete cascade,
  job_id uuid not null references jobs(id) on delete cascade,
  -- Optional: see decision 1 above.
  user_id uuid references profiles(id),
  amount numeric(12,2) not null check (amount >= 0),
  note text,
  recorded_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by uuid references profiles(id),
  delete_reason text
);

create index job_crew_pay_job_idx on job_crew_pay (job_id) where deleted_at is null;

comment on table job_crew_pay is
  'What the crew was paid for a job. Crews are paid per job, not per hour, so '
  'this is the labour cost — there are no hours to multiply by a rate.';

select attach_updated_at('job_crew_pay');
select enable_rls('job_crew_pay');
select attach_audit('job_crew_pay');

-- ---------------------------------------------------------------------------
-- Who may see it, and who may record it
-- ---------------------------------------------------------------------------
--
-- Unlike a price, this needs no masking view: the whole row is a cost, so
-- there is nothing on it to show someone who may not see costs. That makes it
-- a row-level rule, which is what RLS is for.
--
-- Reading is costing.view — the same flag as job cost and margin, which is
-- what this feeds. The crew lead holds price.view and not costing.view, so he
-- sees what the job is worth and not what it cost, which is the line 0028
-- drew.

create policy job_crew_pay_select on job_crew_pay for select
  using (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and (deleted_at is null or has_permission('audit.view'))
  );

-- Writing needs both flags, the same shape as set_job_price(): someone who
-- cannot see what a job cost has no business setting part of it, and could
-- not tell you what they had changed it from.
create policy job_crew_pay_write on job_crew_pay for all
  using (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and has_permission('job.edit')
  )
  with check (
    org_id = auth_org_id()
    and has_permission('costing.view')
    and has_permission('job.edit')
  );

-- Removing one is a soft delete like everything else, so it goes in the
-- registry and comes back through restore_record().
insert into deletable_tables
  (table_name, label, title_column, ref_column, write_permission, parent_table, parent_fk, sort)
values
  ('job_crew_pay', 'Crew pay', 'note', null, 'job.edit', 'jobs', 'job_id', 35);

-- ---------------------------------------------------------------------------
-- Into the costing
-- ---------------------------------------------------------------------------

-- Both of these are `security definer`, and the reason is worth writing down
-- because getting it wrong breaks the costing screens with a permission error.
--
-- `job_labour_cost()` reads `profiles.cost_rate`, which is revoked from the
-- signed-in role. It got away with that as a one-line SQL function because
-- Postgres inlined it into `job_costs`, whose own definer rights covered the
-- read. Adding a second term to it makes inlining a planner's decision rather
-- than a certainty, and the day it declines, every costing screen returns
-- "permission denied for table profiles" to a manager who has done nothing
-- wrong. Definer rights make it deterministic instead of lucky.
--
-- Which means each needs its own gate, since a definer function is reachable
-- directly and RLS no longer applies inside it. Both check costing.view, the
-- same flag `job_costs` checks, so nothing is readable through the function
-- that was not already readable through the view.

create or replace function job_crew_pay_total(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select case
    when not has_permission('costing.view') then
      -- Not an error: this is called per row from a view that has already
      -- excluded anyone without the flag. Reached directly, it says nothing.
      null
    else coalesce((
      select sum(cp.amount)
      from job_crew_pay cp
      join jobs j on j.id = cp.job_id
      where cp.job_id = p_job_id
        and cp.deleted_at is null
        and j.org_id = auth_org_id()
    ), 0)
  end;
$$;

comment on function job_crew_pay_total(uuid) is
  'Flat crew payments recorded against a job. Definer rights, gated on '
  'costing.view and filtered to the caller''s org, exactly like job_costs.';

-- Both sources, added. The hourly half is zero today and stays in place: an
-- hourly crew is the sort of thing a contractor adds later, and when they do,
-- this keeps working without a migration.
create or replace function job_labour_cost(p_job_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select case
    when not has_permission('costing.view') then null
    else
      coalesce((
        select sum(time_entry_hours(t) * coalesce(p.cost_rate, 0))
        from time_entries t
        join profiles p on p.id = t.user_id
        join jobs j on j.id = t.job_id
        where t.job_id = p_job_id
          and t.clock_out_at is not null
          and j.org_id = auth_org_id()
      ), 0)
      + coalesce(job_crew_pay_total(p_job_id), 0)
  end;
$$;

comment on function job_labour_cost(uuid) is
  'Labour on a job: flat crew payments, plus hours times cost rate if anyone '
  'ever records hours. Crews are paid per job here, so in practice it is the '
  'first term. Definer rights, gated on costing.view — see the note above.';

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant select, insert, update, delete on job_crew_pay to authenticated';
  end if;
end $$;

-- ===========================================================
-- 0030_gate_readable_by_the_crew.sql
-- ===========================================================
-- 0030 The completion gate has to be readable by the person it is for
--
-- `job_completion_blockers()` and `job_completion_warnings()` both start with
--
--   select * into v_job from jobs where id = p_job_id;
--
-- and 0027 revoked the price columns on `jobs` from the signed-in role, which
-- makes `select *` there fail by design. Both functions are invoker-rights, so
-- since 0027 every client call has raised
--
--   permission denied for table jobs
--
-- The write path was never affected: `transition_job()` is security definer,
-- so when it checks the gate internally the check runs with its own rights. A
-- job missing its photos could not be completed and still cannot be.
--
-- What broke is the screen that exists to tell a crew what is missing *before
-- they drive away*. The error came back as a null list, the app read that as
-- an empty list, and the completion card said "Nothing outstanding" over an
-- enabled button. Tapping it got a refusal from the server naming a photo
-- nobody had been asked for. The gate was never open; it just stopped
-- explaining itself.
--
-- Definer rights, and a visibility check of their own — a definer function is
-- reachable with any job id, and `can_see_job()` is the same test RLS applies
-- to the row.

create or replace function job_completion_blockers(p_job_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_job jobs;
  v_req jsonb;
  v_blockers text[] := '{}';
  v_form jsonb;
  v_pending int;
begin
  -- Only a client call needs checking. A direct database session — a
  -- migration, a maintenance query, the assertion suite — has no jwt claim at
  -- all, and refusing those would make the function unusable from psql for no
  -- gain: anyone with a database session can read the table anyway.
  if auth_user_id() is not null and not can_see_job(p_job_id) then
    return array['Job not found'];
  end if;

  select * into v_job from jobs where id = p_job_id and deleted_at is null;
  if v_job.id is null then
    return array['Job not found'];
  end if;

  select coalesce(t.completion_requirements, '{}'::jsonb) into v_req
  from job_templates t where t.id = v_job.template_id;
  v_req := coalesce(v_req, '{}'::jsonb);

  if coalesce((v_req ->> 'photos_before')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'before' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'Before photos required');
  end if;

  if coalesce((v_req ->> 'photos_after')::boolean, false)
     and not exists (
       select 1 from job_photos
       where job_id = p_job_id and phase = 'after' and deleted_at is null
     ) then
    v_blockers := array_append(v_blockers, 'After photos required');
  end if;

  if coalesce((v_req ->> 'customer_signature')::boolean, false)
     and not exists (
       select 1 from signatures where job_id = p_job_id and kind = 'completion'
     ) then
    v_blockers := array_append(v_blockers, 'Customer sign-off required');
  end if;

  for v_form in select * from jsonb_array_elements(coalesce(v_req -> 'forms', '[]'::jsonb)) loop
    if not exists (
      select 1
      from form_submissions s
      join form_templates ft on ft.id = s.template_id
      where s.job_id = p_job_id
        and ft.key = (v_form #>> '{}')
        and s.is_complete
    ) then
      v_blockers := array_append(v_blockers, 'Form not complete: ' || (v_form #>> '{}'));
    end if;
  end loop;

  -- Equipment left at a site with no collection arranged stays blocking. It is
  -- the one thing on this list that becomes invisible the moment the crew
  -- leaves, and a forgotten scrubber costs more than the tap it takes to set
  -- a date. The completion screen offers "schedule pickup" inline.
  if exists (
    select 1
    from equipment_assignments a
    where a.job_id = p_job_id
      and a.kind = 'site_staging'
      and a.ended_at is null
      and a.expected_end_at is null
  ) then
    v_blockers := array_append(v_blockers,
      'Equipment still staged at site with no pickup scheduled');
  end if;

  -- Money the customer has not answered on yet. Once the crew drives away it
  -- is never collected, so this one is worth the friction.
  select count(*) into v_pending
  from change_orders where job_id = p_job_id and status in ('draft', 'presented');

  if v_pending > 0 then
    v_blockers := array_append(v_blockers,
      v_pending || ' change order(s) not yet agreed with the customer');
  end if;

  return v_blockers;
end;
$$;

comment on function job_completion_blockers(uuid) is
  'What stands between this job and done. Definer rights because it reads '
  'jobs, whose price columns are revoked from the signed-in role; gated on '
  'can_see_job(), which is the same test RLS applies to the row.';

create or replace function job_completion_warnings(p_job_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_warnings text[] := '{}';
  v_open int;
  v_rentals int;
begin
  -- Same as the blockers: a session with no jwt claim is not a client call.
  if auth_user_id() is not null and not can_see_job(p_job_id) then
    return '{}';
  end if;

  select count(*) into v_open
  from time_entries where job_id = p_job_id and clock_out_at is null;

  if v_open > 0 then
    v_warnings := array_append(v_warnings,
      v_open || ' person(s) will be clocked out now');
  end if;

  -- Any rental still with us at completion, date set or not. "Job finished,
  -- vendor still has gear out" is the signal the office needs; whether a
  -- return date exists is a detail.
  select count(*) into v_rentals
  from equipment_rentals
  where job_id = p_job_id
    and status in ('on_hire', 'overdue');

  if v_rentals > 0 then
    v_warnings := array_append(v_warnings,
      v_rentals || ' rental(s) still out — the office will be told');
  end if;

  return v_warnings;
end;
$$;

comment on function job_completion_warnings(uuid) is
  'True, worth saying, nobody''s reason to stand in a driveway. Definer for '
  'the same reason as the blockers, and gated the same way.';


-- ===========================================================
-- Did it land?
-- ===========================================================
-- Printed by the same transaction that applied it, so there is no
-- second round trip to find out whether it worked. One column per
-- migration in this bundle: every one of them must read true.
select 'Applied' as result,
  exists (select 1 from roles where key = 'crew_lead' and is_system and (permissions ->> 'price.view')::boolean) as crew_lead_price_0028,
  to_regclass('public.job_crew_pay') is not null as crew_pay_0029,
  exists (select 1 from pg_proc where proname = 'job_completion_blockers' and prosecdef) as gate_readable_0030,
  (select count(*) from information_schema.tables
    where table_schema = 'public') as tables,
  (select count(*) from pg_policies where schemaname = 'public') as policies;

commit;
